class Solution {
public:
 int checkWays(vector<vector<int>>& pairs){
  unordered_map<int,unordered_set<int>> adj;
  for(auto& p:pairs){adj[p[0]].insert(p[1]);adj[p[1]].insert(p[0]);}
  int n=adj.size(),root=-1;
  for(auto& e:adj)if((int)e.second.size()==n-1){root=e.first;break;}
  if(root==-1)return 0;
  int ways=1;
  for(auto& e:adj){
   int u=e.first;if(u==root)continue;
   int deg=e.second.size(),parent=-1,parentDeg=INT_MAX;
   for(int v:e.second){int d=adj[v].size();if(d>=deg && d<parentDeg){parent=v;parentDeg=d;}}
   if(parent==-1)return 0;
   for(int v:e.second)if(v!=parent && !adj[parent].count(v))return 0;
   if(parentDeg==deg)ways=2;
  }
  return ways;
 }
};
